package br.com.livraria.book.service; import br.com.livraria.book.model.Categoria; import br.com.livraria.book.repository.CategoriaRepository; import br.com.livraria.book.exception.RecursoNaoEncontradoException; import org.springframework.stereotype.Service; import java.util.List; @Service public class CategoriaService {private final CategoriaRepository repository; public CategoriaService(CategoriaRepository r){repository=r;} public List<Categoria> listar(){return repository.findAll();} public Categoria buscar(Long id){return repository.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Categoria não encontrada: "+id));} public Categoria salvar(Categoria c){return repository.save(c);} public Categoria atualizar(Long id,Categoria dados){Categoria c=buscar(id);c.setNome(dados.getNome());c.setDescricao(dados.getDescricao());return repository.save(c);} public void excluir(Long id){repository.delete(buscar(id));}}